
const json = (data, status=200) => new Response(JSON.stringify(data), {status, headers:{'content-type':'application/json; charset=utf-8','access-control-allow-origin':'*','access-control-allow-methods':'GET,POST,OPTIONS','access-control-allow-headers':'Content-Type, X-Telegram-Init-Data, X-Telegram-User, X-Admin-Key, Accept'}});
const now = () => new Date().toISOString();
const code = () => [...crypto.getRandomValues(new Uint8Array(5))].map(b=>b.toString(16).padStart(2,'0')).join().toUpperCase();
function uid(body){ return String(body?.telegram_id || body?.telegramId || body?.user_id || ''); }
async function user(env, body){
  const tid=uid(body); if(!tid) throw new Error('telegram_id required');
  let u=await env.DB.prepare('SELECT * FROM users WHERE telegram_id=?').bind(tid).first();
  if(!u){
    let rc=code();
    for(let i=0;i<5;i++){ const exists=await env.DB.prepare('SELECT id FROM users WHERE referral_code=?').bind(rc).first(); if(!exists) break; rc=code(); }
    const ref=body.referrer_code ? String(body.referrer_code) : null;
    await env.DB.prepare('INSERT INTO users(telegram_id,username,first_name,last_name,referral_code,referrer_code) VALUES(?,?,?,?,?,?)').bind(tid,body.username||'',body.first_name||'',body.last_name||'',rc,ref).run();
    u=await env.DB.prepare('SELECT * FROM users WHERE telegram_id=?').bind(tid).first();
    if(ref){ const r=await env.DB.prepare('SELECT id FROM users WHERE referral_code=?').bind(ref).first(); if(r) await env.DB.prepare('UPDATE users SET referrals=referrals+1 WHERE id=?').bind(r.id).run(); }
  }
  return u;
}
function pub(u){return {id:u.telegram_id,username:u.username,firstName:u.first_name,lastName:u.last_name,referralCode:u.referral_code,referrerCode:u.referrer_code,wallet:u.wallet_address||'',walletType:u.wallet_type||'',verified:!!u.verified,balance:Number(u.balance||0),taps:Number(u.total_taps||0),referrals:Number(u.referrals||0),successfulReferrals:Number(u.successful_referrals||0),referralReward:Number(u.referral_reward||0),teamWallet:Number(u.team_wallet||0),pendingMining:Number(u.pending_mining||0),level:Number(u.miner_level||1),sound:!!u.sound};}
async function distribute(env, sourceId, claimId, amount){
  const rates=String(env.REFERRAL_RATES||'5,3,2,1,0.5').split(',').map(Number).filter(Number.isFinite);
  const cap=Math.max(0,Number(env.REFERRAL_MAX_TOTAL||15)); let cur=await env.DB.prepare('SELECT referrer_code FROM users WHERE id=?').bind(sourceId).first(); let level=1,total=0,seen=new Set([String(sourceId)]);
  while(cur?.referrer_code && level<=100){ const r=await env.DB.prepare('SELECT id,referrer_code FROM users WHERE referral_code=?').bind(cur.referrer_code).first(); if(!r||seen.has(String(r.id)))break; seen.add(String(r.id)); const rate=Math.min(rates[Math.min(level-1,rates.length-1)]||0,Math.max(0,cap-total)); if(rate<=0)break; const reward=Math.round(amount*rate/100*1e8)/1e8; if(reward>0){const x=await env.DB.prepare('INSERT OR IGNORE INTO referral_earnings(beneficiary_id,source_user_id,source_claim_id,level,rate,amount) VALUES(?,?,?,?,?,?)').bind(r.id,sourceId,String(claimId),level,rate,reward).run(); if(x.meta.changes){await env.DB.prepare('UPDATE users SET team_wallet=COALESCE(team_wallet,0)+?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(reward,r.id).run(); total+=rate;}} cur=r; level++; }
}
async function route(req,env){
 const url=new URL(req.url), p=url.pathname;
 if(req.method==='OPTIONS') return new Response(null,{status:204,headers:{'access-control-allow-origin':'*','access-control-allow-methods':'GET,POST,OPTIONS','access-control-allow-headers':'Content-Type, X-Telegram-Init-Data, X-Telegram-User, X-Admin-Key, Accept'}});
 if(p==='/api/health') return json({ok:true,service:'NayaDost Mining Cloudflare API',time:now()});
 if(p==='/api/price'&&req.method==='GET') return json({ok:true,price:Number(env.NYD_PRICE_FALLBACK||0.001),source:'fallback',updatedAt:now()});
 if(p==='/tonconnect-manifest.json') return json({url:(env.APP_URL||url.origin)+'/',name:'NayaDost Mining',iconUrl:(env.APP_URL||url.origin)+'/icon-180.png'});
 if(!p.startsWith('/api/')) return null;
 let body={}; try{body=await req.json();}catch{}
 try{
  const u=await user(env,body);
  if(p==='/api/bootstrap'){const tasks=await env.DB.prepare('SELECT * FROM tasks WHERE active=1').all(); const claims=await env.DB.prepare('SELECT task_id FROM task_claims WHERE user_id=?').bind(u.id).all(); const day=new Date().toISOString().slice(0,10); const dc=await env.DB.prepare('SELECT id FROM task_claims WHERE user_id=? AND task_id=?').bind(u.id,'daily:'+day).first(); return json({ok:true,user:pub(u),tasks:tasks.results||[],claims:(claims.results||[]).map(x=>x.task_id),dailyClaimed:!!dc,deposit:{address:env.DEPOSIT_ADDRESS,network:'TON',asset:'USDT'},payments:{tonAddress:env.DEPOSIT_ADDRESS,usdtAddress:'',usdtMaster:'EQCxE6mUtQJKFnGfaROTKOt1lZbDiiX1kCixRv7Nw2Id_sDs'},channels:{earn:env.EARN_CHANNEL,official:env.OFFICIAL_CHANNEL}});}
  if(p==='/api/mine'){const day=new Date().toISOString().slice(0,10),key=`mine_${u.id}_${day}`;let m=await env.DB.prepare('SELECT amount FROM deposits WHERE tx_hash=?').bind(key).first();const used=Number(m?.amount||0);if(used>=100)return json({ok:false,error:'Daily 100 tap limit reached'},400);const reward=.01*(1+Math.max(0,Number(u.miner_level||1)-1)*.02);await env.DB.batch([env.DB.prepare('UPDATE users SET pending_mining=COALESCE(pending_mining,0)+?,total_taps=total_taps+1,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(reward,u.id),m?env.DB.prepare('UPDATE deposits SET amount=amount+1 WHERE tx_hash=?').bind(key):env.DB.prepare('INSERT INTO deposits(user_id,tx_hash,amount,asset,network,status) VALUES(?,?,?,?,?,?)').bind(u.id,key,1,'TAPS','LOCAL','Counter')]);const f=await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(u.id).first();return json({ok:true,reward,balance:Number(f.balance||0),pendingMining:Number(f.pending_mining||0),taps:f.total_taps,remaining:99-used});}
  if(p==='/api/claim'){const fresh=await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(u.id).first();const amount=Number(fresh.pending_mining||0);if(amount<=0)return json({ok:false,error:'No mined NYD available to claim'},400);const r=await env.DB.prepare('UPDATE users SET balance=balance+pending_mining,pending_mining=0,updated_at=CURRENT_TIMESTAMP WHERE id=? AND pending_mining>0').bind(u.id).run();if(!r.meta.changes)return json({ok:false,error:'Claim failed. Please try again.'},400);await distribute(env,u.id,'MINE:'+Date.now()+':'+u.id,amount);const f=await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(u.id).first();return json({ok:true,claimed:amount,user:pub(f)});}
  if(p==='/api/referrals/claim'){const x=await env.DB.prepare('SELECT team_wallet FROM users WHERE id=?').bind(u.id).first();const amount=Number(x?.team_wallet||0);if(amount<=0)return json({ok:false,error:'No network rewards available'},400);await env.DB.prepare('UPDATE users SET balance=balance+?,team_wallet=0 WHERE id=? AND team_wallet>0').bind(amount,u.id).run();const f=await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(u.id).first();return json({ok:true,reward:amount,user:pub(f)});}
  if(p==='/api/tasks/telegram-verify') return json({ok:false,error:'Telegram channel verification needs TELEGRAM_BOT_TOKEN configured in this Worker.'},503);
  if(p==='/api/tasks/claim'){const t=await env.DB.prepare('SELECT * FROM tasks WHERE id=? AND active=1').bind(String(body.task_id||'')).first();if(!t)return json({ok:false,error:'Task not found'},400);if(t.type==='telegram')return json({ok:false,error:'Use Telegram Verify for this task'},400);const tid=t.id==='daily'?`daily:${new Date().toISOString().slice(0,10)}`:t.id;const c=await env.DB.prepare('SELECT id FROM task_claims WHERE user_id=? AND task_id=?').bind(u.id,tid).first();if(c)return json({ok:false,error:'Already claimed'},400);const r=await env.DB.prepare('INSERT INTO task_claims(user_id,task_id) VALUES(?,?)').bind(u.id,tid).run();await env.DB.prepare('UPDATE users SET balance=balance+?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(t.reward,u.id).run();await distribute(env,u.id,'TASK:'+r.meta.last_row_id,t.reward);const f=await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(u.id).first();return json({ok:true,claimed:true,reward:t.reward,user:pub(f),dailyKey:t.id==='daily'?tid.slice(6):undefined});}
  if(p==='/api/withdraw'){if(!u.wallet_address||!u.verified)return json({ok:false,error:'Connect and verify a wallet first'},400);const amount=Number(body.amount);if(!Number.isFinite(amount)||amount<10||amount>500)return json({ok:false,error:'Withdrawal must be between 10 and 500 NYD'},400);if(amount>Number(u.balance||0))return json({ok:false,error:'Insufficient balance'},400);const burn=amount*.03,net=amount-burn;await env.DB.batch([env.DB.prepare('UPDATE users SET balance=balance-? WHERE id=?').bind(amount,u.id),env.DB.prepare('INSERT INTO withdrawals(user_id,amount,burn,net,address) VALUES(?,?,?,?,?)').bind(u.id,amount,burn,net,u.wallet_address)]);return json({ok:true,amount,burn,net,balance:Number(u.balance)-amount,status:'Pending'});}
  if(p==='/api/history'){const rows=await env.DB.prepare('SELECT id,amount,burn,net,address,status,admin_note,created_at,updated_at FROM withdrawals WHERE user_id=? ORDER BY id DESC').bind(u.id).all();return json({ok:true,rows:rows.results||[]});}
  if(p==='/api/ton-proof/nonce'){const payload=cryptoRandom();const exp=Math.floor(Date.now()/1000)+900;await env.DB.prepare('UPDATE ton_proof_nonces SET used=1 WHERE user_id=? AND used=0').bind(u.id).run();await env.DB.prepare('INSERT INTO ton_proof_nonces(user_id,payload,expires_at) VALUES(?,?,?)').bind(u.id,payload,exp).run();return json({ok:true,payload,expiresAt:exp});}
  if(p==='/api/ton-proof/verify')return json({ok:false,error:'TON proof verification is not yet implemented in this Cloudflare Worker build. Do not trust an unverified wallet.'},501);
  if(p==='/api/wallet/connect'||p==='/api/verify-wallet')return json({ok:false,error:'Manual wallet binding is disabled. Use TON Connect proof.'},400);
  if(p==='/api/deposit/status')return json({ok:true,configured:false,depositAddress:env.DEPOSIT_ADDRESS,credited:0,balance:Number(u.balance||0)});
  return json({ok:false,error:'API route not implemented'},404);
 }catch(e){return json({ok:false,error:e?.message||'Server error'},400)}
}
function cryptoRandom(){return [...crypto.getRandomValues(new Uint8Array(24))].map(b=>b.toString(16).padStart(2,'0')).join('');}
export default {async fetch(req,env){const r=await route(req,env);if(r)return r;const url=new URL(req.url);if(url.pathname==='/')return new Response(INDEX,{headers:{'content-type':'text/html; charset=utf-8'}});if(url.pathname==='/admin')return new Response('Admin endpoint is available through the Node backend build.',{status:501});return new Response(INDEX,{headers:{'content-type':'text/html; charset=utf-8'}})}};

const INDEX = new TextDecoder().decode(Uint8Array.from(atob(""), c=>c.charCodeAt(0)));
